BehaviorModuleOutput LaneChangeInterface::planWaitingApproval()
{
  BehaviorModuleOutput out = module_type_->getTerminalLaneChangePath();

  module_type_->insert_stop_point(module_type_->get_current_lanes(), out.path, true);
  out.turn_signal_info = module_type_->get_current_turn_signal_info();

  const auto & lane_change_debug = module_type_->getDebugData();
  for (const auto & [uuid, data] : lane_change_debug.collision_check_objects) {
    const auto color = data.is_safe ? ColorName::GREEN : ColorName::RED;
    setObjectsOfInterestData(data.current_obj_pose, data.obj_shape, color);
  }

  path_reference_ = std::make_shared<PathWithLaneId>(out.reference_path);
  stop_pose_ = module_type_->getStopPose();

  if (!module_type_->isValidPath()) {
    path_candidate_ = std::make_shared<PathWithLaneId>();
    updateRTCStatus(
      std::numeric_limits<double>::lowest(), std::numeric_limits<double>::lowest(), false,
      State::WAITING_FOR_EXECUTION);
    module_type_->resetParameters();
    return out;
  }

  const auto candidate = planCandidate();
  path_candidate_ = std::make_shared<PathWithLaneId>(candidate.path_candidate);

  updateRTCStatus(
    candidate.start_distance_to_path_change, candidate.finish_distance_to_path_change,
    isExecutionReady(), State::WAITING_FOR_EXECUTION);
  is_abort_path_approved_ = false;

  set_longitudinal_planning_factor(out.path);

  return out;
}

BehaviorModuleOutput NormalLaneChange::getTerminalLaneChangePath() const
{
  if (
    !lane_change_parameters_->terminal_path.enable ||
    !common_data_ptr_->transient_data.is_ego_near_current_terminal_start) {
    return prev_module_output_;
  }

  const auto is_near_goal = lane_change_parameters_->terminal_path.disable_near_goal &&
                            common_data_ptr_->lanes_ptr->target_lane_in_goal_section &&
                            common_data_ptr_->transient_data.dist_to_target_end <
                              common_data_ptr_->transient_data.lane_changing_length.max;
  if (is_near_goal) {
    return prev_module_output_;
  }

  const auto & current_lanes = get_current_lanes();
  if (current_lanes.empty()) {
    RCLCPP_DEBUG(logger_, "Current lanes not found. Returning previous module's path as output.");
    return prev_module_output_;
  }

  const auto terminal_lc_path = compute_terminal_lane_change_path();

  if (!terminal_lc_path) {
    RCLCPP_DEBUG(logger_, "Terminal path not found. Returning previous module's path as output.");
    return prev_module_output_;
  }

  auto output = prev_module_output_;

  output.path = *terminal_lc_path;
  output.turn_signal_info = get_current_turn_signal_info();

  extendOutputDrivableArea(output);

  return output;
}

const lanelet::ConstLanelets & get_current_lanes() const
{
  return common_data_ptr_->lanes_ptr->current;
}

std::optional<PathWithLaneId> NormalLaneChange::compute_terminal_lane_change_path() const
{
  const auto & transient_data = common_data_ptr_->transient_data;
  const auto dist_to_terminal_start = transient_data.dist_to_terminal_start;
  const auto min_lc_velocity = lane_change_parameters_->trajectory.min_lane_changing_velocity;
  const auto current_velocity = getEgoVelocity();

  PathWithLaneId prepare_segment;
  try {
    if (!utils::lane_change::get_prepare_segment(
          common_data_ptr_, prev_module_output_.path, dist_to_terminal_start, prepare_segment)) {
      RCLCPP_DEBUG(logger_, "failed to get valid prepare segment for terminal LC path");
      return std::nullopt;
    }
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(logger_, "failed to get terminal LC path: %s", e.what());
    return std::nullopt;
  }

  // t = 2 * d / (v1 + v2)
  const auto duration_to_lc_start =
    2.0 * dist_to_terminal_start / (current_velocity + min_lc_velocity);
  const auto lon_accel = std::invoke([&]() -> double {
    if (duration_to_lc_start < calculation::eps) {
      return 0.0;
    }
    return std::clamp(
      (min_lc_velocity - current_velocity) / duration_to_lc_start,
      lane_change_parameters_->trajectory.min_longitudinal_acc,
      lane_change_parameters_->trajectory.max_longitudinal_acc);
  });
  const auto vel_on_prep = current_velocity + lon_accel * duration_to_lc_start;
  const LaneChangePhaseMetrics prep_metric(
    duration_to_lc_start, dist_to_terminal_start, vel_on_prep, lon_accel, lon_accel, 0.0);

  if (terminal_lane_change_path_) {
    terminal_lane_change_path_->info.set_prepare(prep_metric);
    if (prepare_segment.points.empty()) {
      terminal_lane_change_path_->path = terminal_lane_change_path_->shifted_path.path;
      return terminal_lane_change_path_->path;
    }
    prepare_segment.points.pop_back();
    terminal_lane_change_path_->path =
      utils::combinePath(prepare_segment, terminal_lane_change_path_->shifted_path.path);
    return terminal_lane_change_path_->path;
  }

  const auto & lane_changing_start_pose = prepare_segment.points.back().point.pose;
  const auto & target_lanes = common_data_ptr_->lanes_ptr->target;
  const auto shift_length =
    autoware::experimental::lanelet2_utils::get_lateral_distance_to_centerline(
      target_lanes, lane_changing_start_pose);

  const auto dist_lc_start_to_end_of_lanes = calculation::calc_dist_from_pose_to_terminal_end(
    common_data_ptr_, common_data_ptr_->lanes_ptr->target_neighbor,
    prepare_segment.points.back().point.pose);

  const auto max_lane_changing_length = std::invoke([&]() {
    double max_length = transient_data.dist_to_terminal_end - prep_metric.length;
    return std::min(
      max_length, dist_lc_start_to_end_of_lanes - transient_data.next_dist_buffer.min);
  });

  const auto max_path_velocity = prepare_segment.points.back().point.longitudinal_velocity_mps;
  constexpr double lane_changing_lon_accel{0.0};
  const auto lane_changing_metrics = calculation::calc_shift_phase_metrics(
    common_data_ptr_, shift_length, prep_metric.velocity, max_path_velocity,
    lane_changing_lon_accel, max_lane_changing_length);

  const auto sorted_lane_ids = utils::lane_change::get_sorted_lane_ids(common_data_ptr_);

  LaneChangePath candidate_path;
  for (const auto & lc_metric : lane_changing_metrics) {
    try {
      candidate_path = utils::lane_change::get_candidate_path(
        common_data_ptr_, prep_metric, lc_metric, prepare_segment, sorted_lane_ids, shift_length);
    } catch (const std::exception & e) {
      continue;
    }
    terminal_lane_change_path_ = candidate_path;
    return candidate_path.path;
  }

  return std::nullopt;
}

bool get_prepare_segment(
  const CommonDataPtr & common_data_ptr, const PathWithLaneId & prev_module_path,
  const double prep_length, PathWithLaneId & prepare_segment)
{
  const auto & current_lanes = common_data_ptr->lanes_ptr->current;
  const auto & target_lanes = common_data_ptr->lanes_ptr->target;
  const auto backward_path_length = common_data_ptr->bpp_param_ptr->backward_path_length;

  if (current_lanes.empty() || target_lanes.empty()) {
    throw std::logic_error("Empty lanes!");
  }

  prepare_segment = prev_module_path;
  const size_t current_seg_idx =
    autoware::motion_utils::findFirstNearestSegmentIndexWithSoftConstraints(
      prepare_segment.points, common_data_ptr->get_ego_pose(), 3.0, 1.0);
  utils::clipPathLength(prepare_segment, current_seg_idx, prep_length, backward_path_length);

  if (prepare_segment.points.empty()) return false;

  const auto & lc_start_pose = prepare_segment.points.back().point.pose;

  // TODO(Quda, Azu): Is it possible to remove these checks if we ensure prepare segment length is
  // larger than distance to target lane start
  if (!is_valid_start_point(common_data_ptr, lc_start_pose)) return false;

  // lane changing start is at the end of prepare segment
  const auto target_length_from_lane_change_start_pose =
    utils::getArcLengthToTargetLanelet(current_lanes, target_lanes.front(), lc_start_pose);

  // Check if the lane changing start point is not on the lanes next to target lanes,
  if (target_length_from_lane_change_start_pose > std::numeric_limits<double>::epsilon()) {
    throw std::logic_error("lane change start is behind target lanelet!");
  }

  const auto curvatures = calc_curvatures(prepare_segment.points, common_data_ptr->get_ego_pose());

  // curvatures may be empty if ego is near the terminal start of the path.
  if (curvatures.empty()) {
    return true;
  }

  const auto average_curvature = calc_average_curvature(curvatures);

  RCLCPP_DEBUG(get_logger(), "average curvature: %.3f", average_curvature);
  return average_curvature <= common_data_ptr->lc_param_ptr->trajectory.th_prepare_curvature;
}

size_t findFirstNearestSegmentIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  // find first nearest index with soft constraints (not segment index)
  const size_t nearest_idx =
    findFirstNearestIndexWithSoftConstraints(points, pose, dist_threshold, yaw_threshold);

  // calculate segment index
  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, pose.position);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

size_t findFirstNearestIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  validateNonEmpty(points);

  {  // with dist and yaw thresholds
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (squared_dist_threshold < squared_dist || yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with dist threshold
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);

      if (squared_dist_threshold < squared_dist) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with yaw threshold
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  // without any threshold
  return findNearestIndex(points, pose.position);
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_yaw_deviation(
  const geometry_msgs::msg::Pose & base_pose, const geometry_msgs::msg::Pose & target_pose)
{
  const auto base_yaw = tf2::getYaw(base_pose.orientation);
  const auto target_yaw = tf2::getYaw(target_pose.orientation);
  return autoware_utils_math::normalize_radian(target_yaw - base_yaw);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calcLongitudinalOffsetToSegment(
  const T & points, const size_t seg_idx, const geometry_msgs::msg::Point & p_target,
  const bool throw_exception = false)
{
  if (seg_idx >= points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Failed to calculate longitudinal offset because the given segment index is out of the "
      "points size.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto overlap_removed_points = removeOverlapPoints(points, seg_idx);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(get_logger(), "%s", e.what());
      return std::nan("");
    }
  }

  if (seg_idx >= overlap_removed_points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Longitudinal offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto p_front = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx + 1));

  const Eigen::Vector3d segment_vec{p_back.x - p_front.x, p_back.y - p_front.y, 0};
  const Eigen::Vector3d target_vec{p_target.x - p_front.x, p_target.y - p_front.y, 0};

  return segment_vec.dot(target_vec) / segment_vec.norm();
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

void clipPathLength(
  PathWithLaneId & path, const size_t target_idx, const double forward, const double backward)
{
  if (path.points.size() < 3) {
    return;
  }

  const auto start_idx = utils::getIdxByArclength(path, target_idx, -backward);
  const auto end_idx = utils::getIdxByArclength(path, target_idx, forward);

  const std::vector<PathPointWithLaneId> clipped_points{
    path.points.begin() + start_idx, path.points.begin() + end_idx + 1};

  path.points = clipped_points;
}

size_t getIdxByArclength(
  const PathWithLaneId & path, const size_t target_idx, const double signed_arc)
{
  if (path.points.empty()) {
    throw std::runtime_error("[getIdxByArclength] path points must be > 0");
  }

  using autoware_utils::calc_distance2d;
  double sum_length = 0.0;
  if (signed_arc >= 0.0) {
    for (size_t i = target_idx; i < path.points.size() - 1; ++i) {
      const auto next_i = i + 1;
      sum_length += calc_distance2d(path.points.at(i), path.points.at(next_i));
      if (sum_length > signed_arc) {
        return next_i;
      }
    }
    return path.points.size() - 1;
  }
  for (size_t i = target_idx; i > 0; --i) {
    const auto next_i = i - 1;
    sum_length -= calc_distance2d(path.points.at(i), path.points.at(next_i));
    if (sum_length < signed_arc) {
      return next_i;
    }
  }
  return 0;
}

bool is_valid_start_point(const lane_change::CommonDataPtr & common_data_ptr, const Pose & pose)
{
  const lanelet::BasicPoint2d lc_start_point(pose.position.x, pose.position.y);

  const auto & target_neighbor_poly = common_data_ptr->lanes_polygon_ptr->target_neighbor;
  const auto & target_lane_poly = common_data_ptr->lanes_polygon_ptr->target;

  // Check the target lane because the previous approved path might be shifted by avoidance module
  return boost::geometry::covered_by(lc_start_point, target_neighbor_poly) ||
         boost::geometry::covered_by(lc_start_point, target_lane_poly);
}

double getArcLengthToTargetLanelet(
  const lanelet::ConstLanelets & lanelet_sequence, const lanelet::ConstLanelet & target_lane,
  const Pose & pose)
{
  const auto arc_pose =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelet_sequence, pose);

  const auto target_center_line = target_lane.centerline().basicLineString();

  const auto front_pose = to_geom_msg_pose(target_center_line.front(), target_lane);
  const auto back_pose = to_geom_msg_pose(target_center_line.back(), target_lane);

  const auto arc_front =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelet_sequence, front_pose);
  const auto arc_back =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelet_sequence, back_pose);

  return std::max(
    std::min(arc_front.length - arc_pose.length, arc_back.length - arc_pose.length), 0.0);
}

lanelet::ArcCoordinates get_arc_coordinates(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & pose)
{
  // Handle empty Input (Return default ArcCoordinates)
  if (lanelets.empty()) {
    RCLCPP_WARN(
      rclcpp::get_logger("autoware_lanelet2_utility"),
      "Input lanelets is empty. Returning default ArcCoordinates (length=0, distance=0).");
    return lanelet::ArcCoordinates();
  }
  const auto lanelet_sequence = lanelet::LaneletSequence(lanelets);
  const auto centerline_2d = lanelet_sequence.centerline2d();

  const auto lanelet_point = from_ros(pose);

  lanelet::ArcCoordinates arc_coordinates = lanelet::geometry::toArcCoordinates(
    centerline_2d, lanelet::utils::to2D(lanelet_point).basicPoint());

  return arc_coordinates;
}

geometry_msgs::msg::Pose to_geom_msg_pose(
  const lanelet::BasicPoint3d & src_point, const lanelet::ConstLanelet & target_lane)
{
  const auto point = experimental::lanelet2_utils::to_ros(src_point);
  const auto yaw = autoware::experimental::lanelet2_utils::get_lanelet_angle(
    target_lane, autoware::experimental::lanelet2_utils::from_ros(point).basicPoint());
  geometry_msgs::msg::Pose pose;
  pose.position = point;
  tf2::Quaternion quat;
  quat.setRPY(0, 0, yaw);
  pose.orientation = tf2::toMsg(quat);
  return pose;
}

double get_lanelet_angle(
  const lanelet::ConstLanelet & lanelet, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d segment = get_closest_segment(lanelet.centerline(), search_pt);
  return std::atan2(
    segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

std::vector<double> calc_curvatures(
  const std::vector<PathPointWithLaneId> & points, const Pose & current_pose)
{
  const auto nearest_segment_idx =
    autoware::motion_utils::findNearestSegmentIndex(points, current_pose.position);

  // Ignore all path points behind ego vehicle.
  if (points.size() <= nearest_segment_idx + 2) {
    return {};
  }

  std::vector<double> curvatures;
  curvatures.reserve(points.size() - nearest_segment_idx + 2);
  for (const auto & [p1, p2, p3] : ranges::views::zip(
         points | ranges::views::drop(nearest_segment_idx),
         points | ranges::views::drop(nearest_segment_idx + 1),
         points | ranges::views::drop(nearest_segment_idx + 2))) {
    const auto point1 = autoware_utils::get_point(p1);
    const auto point2 = autoware_utils::get_point(p2);
    const auto point3 = autoware_utils::get_point(p3);

    curvatures.push_back(autoware_utils::calc_curvature(point1, point2, point3));
  }

  return curvatures;
}

size_t findNearestSegmentIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  const size_t nearest_idx = findNearestIndex(points, point);

  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, point);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calcLongitudinalOffsetToSegment(
  const T & points, const size_t seg_idx, const geometry_msgs::msg::Point & p_target,
  const bool throw_exception = false)
{
  if (seg_idx >= points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Failed to calculate longitudinal offset because the given segment index is out of the "
      "points size.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto overlap_removed_points = removeOverlapPoints(points, seg_idx);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(get_logger(), "%s", e.what());
      return std::nan("");
    }
  }

  if (seg_idx >= overlap_removed_points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Longitudinal offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto p_front = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx + 1));

  const Eigen::Vector3d segment_vec{p_back.x - p_front.x, p_back.y - p_front.y, 0};
  const Eigen::Vector3d target_vec{p_target.x - p_front.x, p_target.y - p_front.y, 0};

  return segment_vec.dot(target_vec) / segment_vec.norm();
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

