double calc_dist_from_pose_to_terminal_end(
  const CommonDataPtr & common_data_ptr, const lanelet::ConstLanelets & lanes,
  const Pose & src_pose)
{
  if (lanes.empty()) {
    return 0.0;
  }

  const auto in_goal_route_section =
    common_data_ptr->route_handler_ptr->isInGoalRouteSection(lanes.back());
  if (in_goal_route_section) {
    const auto & goal_pose = common_data_ptr->route_handler_ptr->getGoalPose();
    return utils::getSignedDistance(src_pose, goal_pose, lanes);
  }
  return utils::getDistanceToEndOfLane(src_pose, lanes);
}

bool RouteHandler::isInGoalRouteSection(const lanelet::ConstLanelet & lanelet) const
{
  if (!route_ptr_ || route_ptr_->segments.empty()) {
    return false;
  }
  return exists(route_ptr_->segments.back().primitives, lanelet.id());
}

bool exists(const std::vector<LaneletPrimitive> & primitives, const int64_t & id)
{
  for (const auto & p : primitives) {
    if (p.id == id) {
      return true;
    }
  }
  return false;
}

Pose RouteHandler::getGoalPose() const
{
  if (!route_ptr_) {
    RCLCPP_WARN(logger_, "[Route Handler] getGoalPose: Route has not been set yet");
    return Pose();
  }
  return route_ptr_->goal_pose;
}

double getSignedDistance(
  const Pose & current_pose, const Pose & goal_pose, const lanelet::ConstLanelets & lanelets)
{
  const auto arc_current =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelets, current_pose);
  const auto arc_goal =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelets, goal_pose);

  return arc_goal.length - arc_current.length;
}

lanelet::ArcCoordinates get_arc_coordinates(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & pose)
{
  // Handle empty Input (Return default ArcCoordinates)
  if (lanelets.empty()) {
    RCLCPP_WARN(
      rclcpp::get_logger("autoware_lanelet2_utility"),
      "Input lanelets is empty. Returning default ArcCoordinates (length=0, distance=0).");
    return lanelet::ArcCoordinates();
  }
  const auto lanelet_sequence = lanelet::LaneletSequence(lanelets);
  const auto centerline_2d = lanelet_sequence.centerline2d();

  const auto lanelet_point = from_ros(pose);

  lanelet::ArcCoordinates arc_coordinates = lanelet::geometry::toArcCoordinates(
    centerline_2d, lanelet::utils::to2D(lanelet_point).basicPoint());

  return arc_coordinates;
}

double getDistanceToEndOfLane(const Pose & current_pose, const lanelet::ConstLanelets & lanelets)
{
  const auto & arc_coordinates =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelets, current_pose);
  const double lanelet_length = lanelet::geometry::length3d(lanelet::LaneletSequence(lanelets));
  return lanelet_length - arc_coordinates.length;
}

