std::vector<PhaseMetrics> calc_shift_phase_metrics(
  const CommonDataPtr & common_data_ptr, const double shift_length, const double initial_velocity,
  const double max_path_velocity, const double lon_accel, const double max_length_threshold)
{
  const auto & min_lc_vel = common_data_ptr->lc_param_ptr->trajectory.min_lane_changing_velocity;
  const auto & max_vel = common_data_ptr->bpp_param_ptr->max_vel;

  // get lateral acceleration range
  const auto [min_lateral_acc, max_lateral_acc] =
    common_data_ptr->lc_param_ptr->trajectory.lat_acc_map.find(initial_velocity);
  const auto lateral_acc_resolution =
    std::abs(max_lateral_acc - min_lateral_acc) /
    common_data_ptr->lc_param_ptr->trajectory.lat_acc_sampling_num;

  std::vector<PhaseMetrics> metrics;

  auto is_skip = [&](const double lane_changing_length) {
    if (lane_changing_length > max_length_threshold) {
      RCLCPP_DEBUG(
        get_logger(),
        "Skip: lane changing length exceeds maximum threshold. length: %.5f, threshold: %.5f",
        lane_changing_length, max_length_threshold);
      return true;
    }
    return false;
  };

  for (double lat_acc = min_lateral_acc; lat_acc < max_lateral_acc + eps;
       lat_acc += lateral_acc_resolution) {
    const auto lane_changing_duration = autoware::motion_utils::calc_shift_time_from_jerk(
      shift_length, common_data_ptr->lc_param_ptr->trajectory.lateral_jerk, lat_acc);

    const double lane_changing_accel = calc_lane_changing_acceleration(
      common_data_ptr, initial_velocity, max_path_velocity, lane_changing_duration, lon_accel);

    const auto lane_changing_length = calculation::calc_phase_length(
      initial_velocity, max_vel, lane_changing_accel, lane_changing_duration);

    if (is_skip(lane_changing_length)) continue;

    const auto lane_changing_velocity = std::clamp(
      initial_velocity + lane_changing_accel * lane_changing_duration, min_lc_vel, max_vel);

    metrics.emplace_back(
      lane_changing_duration, lane_changing_length, lane_changing_velocity, lon_accel,
      lane_changing_accel, lat_acc);
  }

  return metrics;
}

double calc_shift_time_from_jerk(const double lateral, const double jerk, const double acc)
{
  const double j = std::abs(jerk);
  const double a = std::abs(acc);
  const double l = std::abs(lateral);
  if (j < 1.0e-8 || a < 1.0e-8) {
    const std::string error_message(
      std::string(__func__) + ": Failed to calculate shift time due to invalid arg");
    RCLCPP_WARN(get_logger(), "%s", error_message.c_str());
    return 1.0e10;  // TODO(Horibe) maybe invalid arg?
  }

  // time with constant jerk
  double tj = a / j;

  // time with constant acceleration (zero jerk)
  double ta = (std::sqrt(a * a + 4.0 * j * j * l / a) - 3.0 * a) / (2.0 * j);

  if (ta < 0.0) {
    // it will not hit the acceleration limit this time
    tj = std::pow(l / (2.0 * j), 1.0 / 3.0);
    ta = 0.0;
  }

  const double t_total = 4.0 * tj + 2.0 * ta;
  return t_total;
}

double calc_lane_changing_acceleration(
  const CommonDataPtr & common_data_ptr, const double initial_lane_changing_velocity,
  const double max_path_velocity, const double lane_changing_time,
  const double prepare_longitudinal_acc)
{
  if (prepare_longitudinal_acc <= 0.0) {
    const auto & params = common_data_ptr->lc_param_ptr->trajectory;
    const auto lane_changing_acc =
      common_data_ptr->transient_data.is_ego_near_current_terminal_start
        ? prepare_longitudinal_acc * params.lane_changing_decel_factor
        : 0.0;
    return lane_changing_acc;
  }

  return std::clamp(
    (max_path_velocity - initial_lane_changing_velocity) / lane_changing_time, 0.0,
    prepare_longitudinal_acc);
}

double calc_phase_length(
  const double velocity, const double maximum_velocity, const double acceleration,
  const double duration)
{
  const auto length_with_acceleration =
    velocity * duration + 0.5 * acceleration * std::pow(duration, 2);
  const auto length_with_max_velocity = maximum_velocity * duration;
  return std::min(length_with_acceleration, length_with_max_velocity);
}

std::optional<LaneChangePath> get_candidate_path(
  const TrajectoryGroup & trajectory_group, const CommonDataPtr & common_data_ptr,
  const std::vector<std::vector<int64_t>> & sorted_lane_ids)
{
  if (trajectory_group.lane_changing.frenet_points.empty()) {
    return std::nullopt;
  }

  ShiftedPath shifted_path;
  std::vector<int64_t> prev_ids;
  std::vector<int64_t> prev_sorted_ids;
  const auto & lane_changing_candidate = trajectory_group.lane_changing;
  const auto & target_lane_ref_path = trajectory_group.target_lane_ref_path;
  const auto & prepare_segment = trajectory_group.prepare;
  const auto & prepare_metric = trajectory_group.prepare_metric;
  const auto & initial_state = trajectory_group.initial_state;
  const auto & target_ref_sums = trajectory_group.target_lane_ref_path_dist;
  auto zipped_candidates = ranges::views::zip(
    lane_changing_candidate.poses, lane_changing_candidate.frenet_points,
    lane_changing_candidate.longitudinal_velocities, lane_changing_candidate.lateral_velocities,
    lane_changing_candidate.curvatures);

  shifted_path.path.points.reserve(zipped_candidates.size());
  shifted_path.shift_length.reserve(zipped_candidates.size());
  for (const auto & [pose, frenet_point, longitudinal_velocity, lateral_velocity, curvature] :
       zipped_candidates) {
    // Find the reference index
    const auto & s = frenet_point.s;
    auto ref_i_itr = std::find_if(
      target_ref_sums.begin(), target_ref_sums.end(),
      [s](const double ref_s) { return ref_s > s; });
    auto ref_i = std::distance(target_ref_sums.begin(), ref_i_itr);

    PathPointWithLaneId point;
    point.point.pose = pose;
    point.point.longitudinal_velocity_mps = static_cast<float>(longitudinal_velocity);
    point.point.lateral_velocity_mps = static_cast<float>(lateral_velocity);
    point.point.heading_rate_rps = static_cast<float>(curvature);
    point.point.pose.position.z = target_lane_ref_path.points[ref_i].point.pose.position.z;
    const auto & current_ids = target_lane_ref_path.points[ref_i].lane_ids;
    point.lane_ids =
      replace_with_sorted_ids(current_ids, sorted_lane_ids, prev_ids, prev_sorted_ids);

    // Add to shifted path
    shifted_path.shift_length.push_back(frenet_point.d);
    shifted_path.path.points.push_back(point);
  }

  if (shifted_path.path.points.empty()) {
    return std::nullopt;
  }

  for (auto & point : shifted_path.path.points) {
    point.point.longitudinal_velocity_mps = std::min(
      point.point.longitudinal_velocity_mps,
      static_cast<float>(shifted_path.path.points.back().point.longitudinal_velocity_mps));
  }

  const auto th_yaw_diff_deg = common_data_ptr->lc_param_ptr->frenet.th_yaw_diff_deg;
  if (
    const auto yaw_diff_opt = exceed_yaw_threshold(
      prepare_segment, shifted_path.path, autoware_utils::deg2rad(th_yaw_diff_deg))) {
    const auto yaw_diff_deg = autoware_utils::rad2deg(yaw_diff_opt.value());
    const auto err_msg = fmt::format(
      "Excessive yaw difference {yaw_diff:2.2f}[deg]. The threshold is {th_yaw_diff:2.2f}[deg].",
      fmt::arg("yaw_diff", yaw_diff_deg), fmt::arg("th_yaw_diff", th_yaw_diff_deg));
    throw std::logic_error(err_msg);
  }

  LaneChangeInfo info;
  info.longitudinal_acceleration = {
    prepare_metric.actual_lon_accel, lane_changing_candidate.longitudinal_accelerations.front()};
  info.velocity = {prepare_metric.velocity, initial_state.longitudinal_velocity};
  info.duration = {
    prepare_metric.duration, lane_changing_candidate.sampling_parameter.target_duration};
  info.length = {prepare_metric.length, lane_changing_candidate.lengths.back()};
  info.lane_changing_start = prepare_segment.points.back().point.pose;
  info.lane_changing_end = lane_changing_candidate.poses.back();

  if (utils::lane_change::is_intersecting_no_lane_change_lines(
        common_data_ptr, info.length, shifted_path.path.points)) {
    throw std::logic_error("Intersect no lane change lines.");
  }

  ShiftLine sl;

  sl.start = lane_changing_candidate.poses.front();
  sl.end = lane_changing_candidate.poses.back();
  sl.start_shift_length = 0.0;
  sl.end_shift_length = initial_state.position.d;
  sl.start_idx = 0UL;
  sl.end_idx = shifted_path.shift_length.size() - 1;

  info.shift_line = sl;
  info.terminal_lane_changing_velocity = lane_changing_candidate.longitudinal_velocities.back();
  info.lateral_acceleration = lane_changing_candidate.lateral_accelerations.front();

  LaneChangePath candidate_path;
  candidate_path.path = utils::combinePath(prepare_segment, shifted_path.path);
  candidate_path.info = info;
  candidate_path.shifted_path = shifted_path;
  candidate_path.frenet_path = trajectory_group;
  candidate_path.type = PathType::FrenetPlanner;

  return candidate_path;
}

std::vector<int64_t> replace_with_sorted_ids(
  const std::vector<int64_t> & current_lane_ids,
  const std::vector<std::vector<int64_t>> & sorted_lane_ids, std::vector<int64_t> & prev_lane_ids,
  std::vector<int64_t> & prev_sorted_lane_ids)
{
  if (current_lane_ids == prev_lane_ids) {
    return prev_sorted_lane_ids;
  }

  for (const auto original_id : current_lane_ids) {
    for (const auto & sorted_id : sorted_lane_ids) {
      if (std::find(sorted_id.cbegin(), sorted_id.cend(), original_id) != sorted_id.cend()) {
        prev_lane_ids = current_lane_ids;
        prev_sorted_lane_ids = sorted_id;
        return prev_sorted_lane_ids;
      }
    }
  }

  return current_lane_ids;
}

std::optional<double> exceed_yaw_threshold(
  const PathWithLaneId & prepare_segment, const PathWithLaneId & lane_changing_segment,
  const double yaw_th_rad)
{
  const auto & prepare = prepare_segment.points;
  const auto & lane_changing = lane_changing_segment.points;

  if (prepare.size() <= 1 || lane_changing.size() <= 1) {
    return std::nullopt;
  }

  const auto & p1 = std::prev(prepare.end() - 1)->point.pose;
  const auto & p2 = std::next(lane_changing.begin())->point.pose;
  const auto yaw_diff_rad = std::abs(
    autoware_utils::normalize_radian(tf2::getYaw(p1.orientation) - tf2::getYaw(p2.orientation)));
  if (yaw_diff_rad > yaw_th_rad) {
    return yaw_diff_rad;
  }
  return std::nullopt;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

bool is_intersecting_no_lane_change_lines(
  const CommonDataPtr & common_data_ptr, const PhaseInfo lc_length,
  const std::vector<PathPointWithLaneId> & lane_changing_path)
{
  const auto & intervals = common_data_ptr->transient_data.interval_dist_no_lane_change_lines;
  const auto & lines = common_data_ptr->no_lane_change_lines;
  const auto buffer = common_data_ptr->lc_param_ptr->lane_change_finish_judge_buffer;

  // intervals are sorted in ascending order
  if (intervals.empty() || lc_length.prepare >= intervals.back().second) {
    return false;
  }

  const auto prepare_length = lc_length.prepare;
  const auto total_length = lc_length.sum();
  for (const auto & zip : ranges::views::zip(intervals, lines)) {
    const auto & interval = std::get<0>(zip);
    const auto [interval_start, interval_end] = interval;

    const auto interval_upper_bound = interval_end + buffer;
    if (prepare_length >= interval_upper_bound) {
      continue;
    }

    const auto interval_lower_bound = interval_start - buffer;
    // intervals are sorted in ascending order
    if (total_length <= interval_lower_bound) {
      return false;
    }

    const auto & line = std::get<1>(zip);

    bool is_intersecting =
      ranges::any_of(ranges::views::sliding(lane_changing_path, 2), [&](const auto & path_segment) {
        const auto & path_p1 = path_segment[0].point.pose.position;
        const auto & path_p2 = path_segment[1].point.pose.position;

        for (size_t i = 0; i + 1 < line.size(); ++i) {
          const auto line_p1 = experimental::lanelet2_utils::to_ros(line[i]);
          const auto line_p2 = experimental::lanelet2_utils::to_ros(line[i + 1]);

          if (autoware_utils_geometry::intersect(path_p1, path_p2, line_p1, line_p2)) {
            return true;
          }
        }

        return false;
      });

    if (is_intersecting) {
      return true;
    }
  }

  return false;
}

std::optional<geometry_msgs::msg::Point> intersect(
  const geometry_msgs::msg::Point & p1, const geometry_msgs::msg::Point & p2,
  const geometry_msgs::msg::Point & p3, const geometry_msgs::msg::Point & p4)
{
  // Compute the determinant to check if the two lines are parallel.
  // If det is close to zero, the lines are nearly parallel and there's
  // no unique intersection point.
  const double det = (p1.x - p2.x) * (p4.y - p3.y) - (p4.x - p3.x) * (p1.y - p2.y);

  // A small tolerance factor for geometric computations.
  // Used to make the intersection detection more robust against
  // floating-point precision errors and to handle borderline cases consistently.
  constexpr double geometric_epsilon = 1e-9;

  if (std::abs(det) < geometric_epsilon) {
    // Lines are nearly parallel — treat this as no single intersection point.
    return std::nullopt;
  }

  const double t = ((p4.y - p3.y) * (p4.x - p2.x) + (p3.x - p4.x) * (p4.y - p2.y)) / det;
  const double s = ((p2.y - p1.y) * (p4.x - p2.x) + (p1.x - p2.x) * (p4.y - p2.y)) / det;

  // Helper function to check whether the intersection parameter is slightly
  // outside the [0, 1] range, considering a small tolerance margin.
  const auto is_outside_interval = [&](const double t) {
    return t < -geometric_epsilon || (1.0 + geometric_epsilon) < t;
  };

  // check collision is outside the segment line
  // Check if the computed intersection lies outside the segment boundaries.
  // The tolerance helps to avoid jitter or inconsistent results for
  // near-boundary cases caused by floating-point errors.
  if (is_outside_interval(t) || is_outside_interval(s)) {
    return std::nullopt;
  }

  geometry_msgs::msg::Point intersect_point;
  intersect_point.x = t * p1.x + (1.0 - t) * p2.x;
  intersect_point.y = t * p1.y + (1.0 - t) * p2.y;
  intersect_point.z = t * p1.z + (1.0 - t) * p2.z;
  return intersect_point;
}

PathWithLaneId combinePath(const PathWithLaneId & path1, const PathWithLaneId & path2)
{
  if (path1.points.empty()) {
    return path2;
  }
  if (path2.points.empty()) {
    return path1;
  }

  PathWithLaneId path{};
  path.points.insert(path.points.end(), path1.points.begin(), path1.points.end());

  // skip overlapping point
  path.points.insert(path.points.end(), next(path2.points.begin()), path2.points.end());

  PathWithLaneId filtered_path = path;
  filtered_path.points = autoware::motion_utils::removeOverlapPoints(filtered_path.points);
  return filtered_path;
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

TurnSignalInfo NormalLaneChange::get_current_turn_signal_info() const
{
  const auto original_turn_signal_info = prev_module_output_.turn_signal_info;

  if (getModuleType() != LaneChangeModuleType::NORMAL || get_current_lanes().empty()) {
    return original_turn_signal_info;
  }

  if (direction_ != Direction::LEFT && direction_ != Direction::RIGHT) {
    return original_turn_signal_info;
  }

  const auto & prev_path = prev_module_output_.path.points;
  if (prev_path.empty()) {
    return original_turn_signal_info;
  }

  const auto & original_command = original_turn_signal_info.turn_signal.command;
  if (
    original_command != TurnIndicatorsCommand::DISABLE &&
    original_command != TurnIndicatorsCommand::NO_COMMAND) {
    return get_terminal_turn_signal_info();
  }

  if (!status_.is_valid_path) {
    return get_turn_signal(getEgoPose(), prev_path.back().point.pose);
  }

  set_signal_activation_time();

  return get_turn_signal(getEgoPose(), getLaneChangePath().info.lane_changing_end);
}

TurnSignalInfo NormalLaneChange::get_terminal_turn_signal_info() const
{
  const auto & lane_change_param = getLaneChangeParam();
  const auto & common_param = getCommonParam();
  const auto & current_pose = getEgoPose();
  const auto & path = prev_module_output_.path;

  const auto original_turn_signal_info = prev_module_output_.turn_signal_info;

  const auto buffer = common_data_ptr_->transient_data.current_dist_buffer.min +
                      lane_change_param.min_length_for_turn_signal_activation +
                      common_param.base_link2front;
  const double path_length = autoware::motion_utils::calcArcLength(path.points);
  const auto start_pose = autoware::motion_utils::calcLongitudinalOffsetPose(
    path.points, 0, std::max(path_length - buffer, 0.0));

  if (!start_pose) return original_turn_signal_info;

  const auto terminal_turn_signal_info =
    get_turn_signal(*start_pose, getLaneChangePath().info.lane_changing_end);

  const auto nearest_dist_threshold = common_param.ego_nearest_dist_threshold;
  const auto nearest_yaw_threshold = common_param.ego_nearest_yaw_threshold;
  const auto current_nearest_seg_idx = common_data_ptr_->transient_data.current_path_seg_idx;

  const auto turn_signal_info = getTurnSignalDecider().overwrite_turn_signal(
    path, current_pose, current_nearest_seg_idx, original_turn_signal_info,
    terminal_turn_signal_info, nearest_dist_threshold, nearest_yaw_threshold);

  set_signal_activation_time(
    turn_signal_info.turn_signal.command != terminal_turn_signal_info.turn_signal.command);

  return turn_signal_info;
}

std::optional<geometry_msgs::msg::Pose> calcLongitudinalOffsetPose(
  const T & points, const size_t src_idx, const double offset,
  const bool set_orientation_from_position_direction = true, const bool throw_exception = false)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "Failed to calculate longitudinal offset: %s", e.what());
    return {};
  }

  if (points.size() - 1 < src_idx) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      " error: The given source index is out of the points size. Failed to calculate longitudinal "
      "offset.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(get_logger(), "%s", error_message.c_str());
    return {};
  }

  if (points.size() == 1) {
    RCLCPP_DEBUG(get_logger(), "Failed to calculate longitudinal offset: points size is one.");
    return {};
  }

  if (src_idx + 1 == points.size() && offset == 0.0) {
    return autoware_utils_geometry::get_pose(points.at(src_idx));
  }

  if (offset < 0.0) {
    auto reverse_points = points;
    std::reverse(reverse_points.begin(), reverse_points.end());

    double dist_sum = 0.0;

    for (size_t i = reverse_points.size() - src_idx - 1; i < reverse_points.size() - 1; ++i) {
      const auto & p_front = reverse_points.at(i);
      const auto & p_back = reverse_points.at(i + 1);

      const auto dist_segment = autoware_utils_geometry::calc_distance2d(p_front, p_back);
      dist_sum += dist_segment;

      const auto dist_res = -offset - dist_sum;
      if (dist_res <= 0.0) {
        return autoware_utils_geometry::calc_interpolated_pose(
          p_back, p_front, std::abs(dist_res / dist_segment),
          set_orientation_from_position_direction);
      }
    }
  } else {
    double dist_sum = 0.0;

    for (size_t i = src_idx; i < points.size() - 1; ++i) {
      const auto & p_front = points.at(i);
      const auto & p_back = points.at(i + 1);

      const auto dist_segment = autoware_utils_geometry::calc_distance2d(p_front, p_back);
      dist_sum += dist_segment;

      const auto dist_res = offset - dist_sum;
      if (dist_res <= 0.0) {
        return autoware_utils_geometry::calc_interpolated_pose(
          p_front, p_back, 1.0 - std::abs(dist_res / dist_segment),
          set_orientation_from_position_direction);
      }
    }
  }

  // not found (out of range)
  return {};
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Pose calc_interpolated_pose(
  const Pose1 & src_pose, const Pose2 & dst_pose, const double ratio,
  const bool set_orientation_from_position_direction = true)
{
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);

  geometry_msgs::msg::Pose output_pose;
  output_pose.position =
    calc_interpolated_point(get_point(src_pose), get_point(dst_pose), clamped_ratio);

  if (set_orientation_from_position_direction) {
    const double input_poses_dist = calc_distance2d(get_point(src_pose), get_point(dst_pose));
    const bool is_driving_forward_flag = is_driving_forward(src_pose, dst_pose);

    // Get orientation from interpolated point and src_pose
    if ((is_driving_forward_flag && clamped_ratio > 1.0 - (1e-6)) || input_poses_dist < 1e-3) {
      output_pose.orientation = get_pose(dst_pose).orientation;
    } else if (!is_driving_forward_flag && clamped_ratio < 1e-6) {
      output_pose.orientation = get_pose(src_pose).orientation;
    } else {
      const auto & base_pose = is_driving_forward_flag ? dst_pose : src_pose;
      const double pitch = calc_elevation_angle(get_point(output_pose), get_point(base_pose));
      const double yaw = calc_azimuth_angle(get_point(output_pose), get_point(base_pose));
      output_pose.orientation = create_quaternion_from_rpy(0.0, pitch, yaw);
    }
  } else {
    // Get orientation by spherical linear interpolation
    tf2::Transform src_tf;
    tf2::Transform dst_tf;
    tf2::fromMsg(get_pose(src_pose), src_tf);
    tf2::fromMsg(get_pose(dst_pose), dst_tf);
    const auto & quaternion = tf2::slerp(src_tf.getRotation(), dst_tf.getRotation(), clamped_ratio);
    output_pose.orientation = tf2::toMsg(quaternion);
  }

  return output_pose;
}

geometry_msgs::msg::Point calc_interpolated_point(
  const Point1 & src, const Point2 & dst, const double ratio)
{
  const auto src_point = get_point(src);
  const auto dst_point = get_point(dst);

  tf2::Vector3 src_vec;
  src_vec.setX(src_point.x);
  src_vec.setY(src_point.y);
  src_vec.setZ(src_point.z);

  tf2::Vector3 dst_vec;
  dst_vec.setX(dst_point.x);
  dst_vec.setY(dst_point.y);
  dst_vec.setZ(dst_point.z);

  // Get pose by linear interpolation
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);
  const auto & vec = tf2::lerp(src_vec, dst_vec, clamped_ratio);

  geometry_msgs::msg::Point point;
  point.x = vec.x();
  point.y = vec.y();
  point.z = vec.z();

  return point;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool is_driving_forward(const Pose1 & src_pose, const Pose2 & dst_pose)
{
  // check the first point direction
  const double src_yaw = tf2::getYaw(get_pose(src_pose).orientation);
  const double pose_direction_yaw = calc_azimuth_angle(get_point(src_pose), get_point(dst_pose));
  return std::fabs(normalize_radian(src_yaw - pose_direction_yaw)) < pi / 2.0;
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Quaternion create_quaternion_from_rpy(
  const double roll, const double pitch, const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(roll, pitch, yaw);
  return tf2::toMsg(q);
}

TurnSignalInfo get_turn_signal(const Pose & start, const Pose & end) const
{
  TurnSignalInfo turn_signal;
  switch (direction_) {
    case Direction::LEFT:
      turn_signal.turn_signal.command = TurnIndicatorsCommand::ENABLE_LEFT;
      break;
    case Direction::RIGHT:
      turn_signal.turn_signal.command = TurnIndicatorsCommand::ENABLE_RIGHT;
      break;
    default:
      turn_signal.turn_signal.command = TurnIndicatorsCommand::NO_COMMAND;
      break;
  }

  turn_signal.desired_start_point = start;
  turn_signal.desired_end_point = end;
  turn_signal.required_start_point = turn_signal.desired_start_point;
  turn_signal.required_end_point = turn_signal.desired_end_point;

  return turn_signal;
}

TurnSignalInfo TurnSignalDecider::overwrite_turn_signal(
  const PathWithLaneId & path, const Pose & current_pose, const size_t current_seg_idx,
  const TurnSignalInfo & original_signal, const TurnSignalInfo & new_signal,
  const double nearest_dist_threshold, const double nearest_yaw_threshold) const
{
  if (original_signal.turn_signal.command == TurnIndicatorsCommand::NO_COMMAND) {
    return new_signal;
  }

  if (original_signal.turn_signal.command == TurnIndicatorsCommand::DISABLE) {
    return new_signal;
  }

  const auto get_distance = [&](const Pose & input_point) {
    const size_t nearest_seg_idx =
      autoware::motion_utils::findFirstNearestSegmentIndexWithSoftConstraints(
        path.points, input_point, nearest_dist_threshold, nearest_yaw_threshold);
    return autoware::motion_utils::calcSignedArcLength(
             path.points, current_pose.position, current_seg_idx, input_point.position,
             nearest_seg_idx) -
           base_link2front_;
  };

  const auto & original_desired_end_point = original_signal.desired_end_point;
  const auto & new_desired_start_point = new_signal.desired_start_point;

  const double dist_to_original_desired_end = get_distance(original_desired_end_point);
  const double dist_to_new_desired_start = get_distance(new_desired_start_point);
  if (dist_to_new_desired_start > dist_to_original_desired_end) {
    return original_signal;
  }

  return new_signal;
}

size_t findFirstNearestSegmentIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  // find first nearest index with soft constraints (not segment index)
  const size_t nearest_idx =
    findFirstNearestIndexWithSoftConstraints(points, pose, dist_threshold, yaw_threshold);

  // calculate segment index
  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, pose.position);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

size_t findFirstNearestIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  validateNonEmpty(points);

  {  // with dist and yaw thresholds
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (squared_dist_threshold < squared_dist || yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with dist threshold
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);

      if (squared_dist_threshold < squared_dist) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with yaw threshold
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  // without any threshold
  return findNearestIndex(points, pose.position);
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_yaw_deviation(
  const geometry_msgs::msg::Pose & base_pose, const geometry_msgs::msg::Pose & target_pose)
{
  const auto base_yaw = tf2::getYaw(base_pose.orientation);
  const auto target_yaw = tf2::getYaw(target_pose.orientation);
  return autoware_utils_math::normalize_radian(target_yaw - base_yaw);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calcLongitudinalOffsetToSegment(
  const T & points, const size_t seg_idx, const geometry_msgs::msg::Point & p_target,
  const bool throw_exception = false)
{
  if (seg_idx >= points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Failed to calculate longitudinal offset because the given segment index is out of the "
      "points size.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto overlap_removed_points = removeOverlapPoints(points, seg_idx);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(get_logger(), "%s", e.what());
      return std::nan("");
    }
  }

  if (seg_idx >= overlap_removed_points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Longitudinal offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto p_front = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx + 1));

  const Eigen::Vector3d segment_vec{p_back.x - p_front.x, p_back.y - p_front.y, 0};
  const Eigen::Vector3d target_vec{p_target.x - p_front.x, p_target.y - p_front.y, 0};

  return segment_vec.dot(target_vec) / segment_vec.norm();
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

