bool exists(const std::vector<LaneletPrimitive> & primitives, const int64_t & id)
{
  for (const auto & p : primitives) {
    if (p.id == id) {
      return true;
    }
  }
  return false;
}

lanelet::ConstLanelets RouteHandler::getNextLanelets(const lanelet::ConstLanelet & lanelet) const
{
  return routing_graph_ptr_->following(lanelet);
}

std::vector<DrivableLanes> cutOverlappedLanes(
  PathWithLaneId & path, const std::vector<DrivableLanes> & lanes)
{
  const auto overlapped_lanelet_idx = getOverlappedLaneletId(lanes);
  if (!overlapped_lanelet_idx) {
    return lanes;
  }

  std::vector<DrivableLanes> shorten_lanes{lanes.begin(), lanes.begin() + *overlapped_lanelet_idx};
  const auto shorten_lanelets = utils::transformToLanelets(shorten_lanes);

  const auto original_points = path.points;

  path.points.clear();

  const auto has_same_id_lane = [](const auto & lanelet, const auto & p) {
    return std::any_of(p.lane_ids.begin(), p.lane_ids.end(), [&lanelet](const auto id) {
      return lanelet.id() == id;
    });
  };

  const auto has_same_id_lanes = [&has_same_id_lane](const auto & lanelets, const auto & p) {
    return std::any_of(
      lanelets.begin(), lanelets.end(),
      [&has_same_id_lane, &p](const auto & lanelet) { return has_same_id_lane(lanelet, p); });
  };

  const auto is_point_in_drivable_lanes = [&has_same_id_lane, &has_same_id_lanes](
                                            const auto & lanes, const auto & p) {
    if (has_same_id_lane(lanes.right_lane, p)) {
      return true;
    }
    // check left lane
    if (has_same_id_lane(lanes.left_lane, p)) {
      return true;
    }
    // check middle lanes
    if (has_same_id_lanes(lanes.middle_lanes, p)) {
      return true;
    }
    return false;
  };

  // Step1. find first path point within drivable lanes
  size_t start_point_idx = original_points.size();

  for (size_t i = 0; i < original_points.size(); ++i) {
    const bool first_path_point_in_drivable_lane_found = std::any_of(
      shorten_lanes.begin(), shorten_lanes.end(),
      [&is_point_in_drivable_lanes, &original_points, i](const auto & lanes) {
        return is_point_in_drivable_lanes(lanes, original_points.at(i));
      });
    if (first_path_point_in_drivable_lane_found) {
      start_point_idx = i;
      break;
    }
  }

  // Step2. pick up only path points within drivable lanes
  std::set<size_t> path_point_indices;
  for (const auto & drivable_lanes : shorten_lanes) {
    for (size_t i = start_point_idx; i < original_points.size(); ++i) {
      const auto & p = original_points.at(i);
      if (is_point_in_drivable_lanes(drivable_lanes, p) && path_point_indices.count(i) == 0) {
        path.points.push_back(p);
        path_point_indices.insert(i);
        continue;
      }
      start_point_idx = i;
      break;
    }
  }

  return shorten_lanes;
}

std::optional<size_t> getOverlappedLaneletId(const std::vector<DrivableLanes> & lanes)
{
  auto overlaps = [](const DrivableLanes & lanes, const DrivableLanes & target_lanes) {
    const auto lanelets = utils::transformToLanelets(lanes);
    const auto target_lanelets = utils::transformToLanelets(target_lanes);

    for (const auto & lanelet : lanelets) {
      for (const auto & target_lanelet : target_lanelets) {
        std::vector<Polygon2d> intersections{};
        boost::geometry::intersection(
          toPolygon2d(lanelet), toPolygon2d(target_lanelet), intersections);

        for (const auto & polygon : intersections) {
          if (boost::geometry::area(polygon) > 1e-3) {
            return true;
          }
        }
      }
    }

    // No overlapping
    return false;
  };

  if (lanes.size() <= 2) {
    return {};
  }

  for (size_t i = 0; i < lanes.size() - 2; ++i) {
    for (size_t j = i + 2; j < lanes.size(); ++j) {
      if (overlaps(lanes.at(i), lanes.at(j))) {
        return j;
      }
    }
  }

  return {};
}

lanelet::ConstLanelets transformToLanelets(const DrivableLanes & drivable_lanes)
{
  lanelet::ConstLanelets lanes;

  const auto has_same_lane = [&](const auto & lane) {
    if (lanes.empty()) return false;
    const auto has_same = [&](const auto & ll) { return ll.id() == lane.id(); };
    return std::find_if(lanes.begin(), lanes.end(), has_same) != lanes.end();
  };

  lanes.push_back(drivable_lanes.right_lane);
  if (!has_same_lane(drivable_lanes.left_lane)) {
    lanes.push_back(drivable_lanes.left_lane);
  }

  for (const auto & ml : drivable_lanes.middle_lanes) {
    if (!has_same_lane(ml)) {
      lanes.push_back(ml);
    }
  }

  return lanes;
}

lanelet::ConstLanelets transformToLanelets(const DrivableLanes & drivable_lanes)
{
  lanelet::ConstLanelets lanes;

  const auto has_same_lane = [&](const auto & lane) {
    if (lanes.empty()) return false;
    const auto has_same = [&](const auto & ll) { return ll.id() == lane.id(); };
    return std::find_if(lanes.begin(), lanes.end(), has_same) != lanes.end();
  };

  lanes.push_back(drivable_lanes.right_lane);
  if (!has_same_lane(drivable_lanes.left_lane)) {
    lanes.push_back(drivable_lanes.left_lane);
  }

  for (const auto & ml : drivable_lanes.middle_lanes) {
    if (!has_same_lane(ml)) {
      lanes.push_back(ml);
    }
  }

  return lanes;
}

std::vector<DrivableLanes> expandLanelets(
  const std::vector<DrivableLanes> & drivable_lanes, const double left_bound_offset,
  const double right_bound_offset, const std::vector<std::string> & types_to_skip)
{
  using autoware::experimental::lanelet2_utils::get_dirty_expanded_lanelet;
  if (left_bound_offset == 0.0 && right_bound_offset == 0.0) return drivable_lanes;

  std::vector<DrivableLanes> expanded_drivable_lanes{};
  expanded_drivable_lanes.reserve(drivable_lanes.size());
  for (const auto & lanes : drivable_lanes) {
    const std::string l_type =
      lanes.left_lane.leftBound().attributeOr(lanelet::AttributeName::Type, "none");
    const std::string r_type =
      lanes.right_lane.rightBound().attributeOr(lanelet::AttributeName::Type, "none");

    const bool l_skip =
      std::find(types_to_skip.begin(), types_to_skip.end(), l_type) != types_to_skip.end();
    const bool r_skip =
      std::find(types_to_skip.begin(), types_to_skip.end(), r_type) != types_to_skip.end();
    const double l_offset = l_skip ? 0.0 : left_bound_offset;
    const double r_offset = r_skip ? 0.0 : -right_bound_offset;

    DrivableLanes expanded_lanes;
    std::optional<lanelet::ConstLanelet> expanded_left_lane_opt;
    std::optional<lanelet::ConstLanelet> expanded_right_lane_opt;
    if (lanes.left_lane.id() == lanes.right_lane.id()) {
      expanded_left_lane_opt = get_dirty_expanded_lanelet(lanes.left_lane, l_offset, r_offset);
      expanded_right_lane_opt = get_dirty_expanded_lanelet(lanes.right_lane, l_offset, r_offset);
    } else {
      expanded_left_lane_opt = get_dirty_expanded_lanelet(lanes.left_lane, l_offset, 0.0);
      expanded_right_lane_opt = get_dirty_expanded_lanelet(lanes.right_lane, 0.0, r_offset);
    }
    expanded_lanes.left_lane =
      expanded_left_lane_opt.has_value() ? expanded_left_lane_opt.value() : lanes.left_lane;
    expanded_lanes.right_lane =
      expanded_right_lane_opt.has_value() ? expanded_right_lane_opt.value() : lanes.right_lane;

    expanded_lanes.middle_lanes = lanes.middle_lanes;
    expanded_drivable_lanes.push_back(expanded_lanes);
  }
  return expanded_drivable_lanes;
}

std::optional<lanelet::ConstLanelet> get_dirty_expanded_lanelet(
  const lanelet::ConstLanelet & lanelet_obj, const double left_offset, const double right_offset)
{
  const auto copy_z = [](const lanelet::ConstLineString3d & from, lanelet::Points3d & to) {
    lanelet::Points3d new_to = to;
    if (from.empty() || to.empty()) return to;
    new_to.front().z() = from.front().z();
    if (from.size() < 2 || to.size() < 2) return new_to;
    new_to.back().z() = from.back().z();
    auto i_from = 1lu;
    auto s_from = lanelet::geometry::distance2d(from[0], from[1]);
    auto s_to = 0.0;
    auto s_from_prev = 0.0;
    for (auto i_to = 1lu; i_to + 1 < to.size(); ++i_to) {
      s_to += lanelet::geometry::distance2d(new_to[i_to - 1], new_to[i_to]);
      for (; s_from < s_to && i_from + 1 < from.size(); ++i_from) {
        s_from_prev = s_from;
        s_from += lanelet::geometry::distance2d(from[i_from], from[i_from + 1]);
      }
      const auto ratio = (s_to - s_from_prev) / (s_from - s_from_prev);
      new_to[i_to].z() = from[i_from - 1].z() + ratio * (from[i_from].z() - from[i_from - 1].z());
    }
    return new_to;
  };

  const auto to_points3d = [](const lanelet::BasicLineString2d & ls2d) {
    lanelet::Points3d output;
    for (const auto & pt : ls2d) {
      output.push_back(lanelet::Point3d(lanelet::InvalId, pt.x(), pt.y(), 0.0));
    }
    return output;
  };

  using lanelet::geometry::offsetNoThrow;
  using lanelet::geometry::internal::checkForInversion;

  const auto & orig_left_bound_2d = lanelet_obj.leftBound2d().basicLineString();
  const auto & orig_right_bound_2d = lanelet_obj.rightBound2d().basicLineString();

  // Note: The lanelet::geometry::offset throws exception when the undesired inversion is found.
  // Use offsetNoThrow until the logic is updated to handle the inversion.
  // TODO(Horibe) update
  // Note: this is ported from autoware_lanelet2_extension
  auto expanded_left_bound_2d = offsetNoThrow(orig_left_bound_2d, left_offset);
  auto expanded_right_bound_2d = offsetNoThrow(orig_right_bound_2d, right_offset);

  rclcpp::Clock clock{RCL_ROS_TIME};
  try {
    checkForInversion(orig_left_bound_2d, expanded_left_bound_2d, left_offset);
    checkForInversion(orig_right_bound_2d, expanded_right_bound_2d, right_offset);
  } catch (const lanelet::GeometryError & e) {
    RCLCPP_ERROR_THROTTLE(
      rclcpp::get_logger("autoware_lanelet2_utility"), clock, 1000,
      "Fail to expand lanelet. output may be undesired. Lanelet points interval in map data "
      "could "
      "be too narrow.");
  }

  lanelet::Points3d ex_lefts = to_points3d(expanded_left_bound_2d);
  lanelet::Points3d ex_rights = to_points3d(expanded_right_bound_2d);
  copy_z(lanelet_obj.leftBound3d(), ex_lefts);
  copy_z(lanelet_obj.rightBound3d(), ex_rights);

  auto convert_to_const = [](const lanelet::Points3d from) {
    lanelet::ConstPoints3d to;
    for (const auto & pt : from) {
      to.emplace_back(pt);
    }
    return to;
  };

  auto const_ex_lefts = convert_to_const(ex_lefts);
  auto const_ex_rights = convert_to_const(ex_rights);
  const auto & lanelet_opt = create_safe_lanelet(const_ex_lefts, const_ex_rights);
  assert(lanelet_opt.has_value() && "lefts or rights bound size is less than 2.");

  // return optional value
  return lanelet_opt;
}

std::optional<lanelet::ConstLanelet> create_safe_lanelet(
  const lanelet::ConstLineString3d & left_linestring,
  const lanelet::ConstLineString3d & right_linestring)
{
  if (left_linestring.size() < 2 || right_linestring.size() < 2) {
    return std::nullopt;
  }

  const auto left_ls = remove_const(left_linestring);
  const auto right_ls = remove_const(right_linestring);

  return lanelet::ConstLanelet{lanelet::InvalId, left_ls, right_ls};
}

lanelet::LineString3d remove_const(const lanelet::ConstLineString3d & const_linestring)
{
  return lanelet::LineString3d{
    std::const_pointer_cast<lanelet::LineStringData>(const_linestring.constData())};
}

DrivableAreaInfo combineDrivableAreaInfo(
  const DrivableAreaInfo & drivable_area_info1, const DrivableAreaInfo & drivable_area_info2)
{
  DrivableAreaInfo combined_drivable_area_info;

  // drivable lanes
  combined_drivable_area_info.drivable_lanes =
    combineDrivableLanes(drivable_area_info1.drivable_lanes, drivable_area_info2.drivable_lanes);

  // obstacles
  for (const auto & obstacle : drivable_area_info1.obstacles) {
    combined_drivable_area_info.obstacles.push_back(obstacle);
  }
  for (const auto & obstacle : drivable_area_info2.obstacles) {
    combined_drivable_area_info.obstacles.push_back(obstacle);
  }

  // enable expanding hatched road markings
  combined_drivable_area_info.enable_expanding_hatched_road_markings =
    drivable_area_info1.enable_expanding_hatched_road_markings ||
    drivable_area_info2.enable_expanding_hatched_road_markings;

  // enable expanding intersection areas
  combined_drivable_area_info.enable_expanding_intersection_areas =
    drivable_area_info1.enable_expanding_intersection_areas ||
    drivable_area_info2.enable_expanding_intersection_areas;

  // enable expanding freespace areas
  combined_drivable_area_info.enable_expanding_freespace_areas =
    drivable_area_info1.enable_expanding_freespace_areas ||
    drivable_area_info2.enable_expanding_freespace_areas;

  // drivable margin
  combined_drivable_area_info.drivable_margin =
    std::max(drivable_area_info1.drivable_margin, drivable_area_info2.drivable_margin);

  return combined_drivable_area_info;
}

std::vector<DrivableLanes> combineDrivableLanes(
  const std::vector<DrivableLanes> & original_drivable_lanes_vec,
  const std::vector<DrivableLanes> & new_drivable_lanes_vec)
{
  const auto has_same_lane =
    [](const lanelet::ConstLanelet & target_lane, const lanelet::ConstLanelets & lanes) {
      return std::find_if(lanes.begin(), lanes.end(), [&](const auto & ll) {
               return ll.id() == target_lane.id() &&
                      ll.rightBound3d().id() == target_lane.rightBound3d().id() &&
                      ll.leftBound3d().id() == target_lane.leftBound3d().id();
             }) != lanes.end();
    };

  const auto convert_to_lanes = [](const DrivableLanes & drivable_lanes) {
    auto lanes = drivable_lanes.middle_lanes;
    lanes.push_back(drivable_lanes.right_lane);
    lanes.push_back(drivable_lanes.left_lane);
    return lanes;
  };

  auto updated_drivable_lanes_vec = original_drivable_lanes_vec;
  size_t new_drivable_lanes_idx = 0;
  for (auto & updated_drivable_lanes : updated_drivable_lanes_vec) {
    // calculated corresponding index of new_drivable_lanes
    const auto opt_new_drivable_lanes_idx = [&]() -> std::optional<size_t> {
      for (size_t n_idx = 0; n_idx < new_drivable_lanes_vec.size(); ++n_idx) {
        for (const auto & ll : convert_to_lanes(updated_drivable_lanes)) {
          if (has_same_lane(ll, convert_to_lanes(new_drivable_lanes_vec.at(n_idx)))) {
            return n_idx;
          }
        }
      }
      return std::nullopt;
    }();
    if (!opt_new_drivable_lanes_idx) {
      continue;
    }
    new_drivable_lanes_idx = *opt_new_drivable_lanes_idx;
    const auto & new_drivable_lanes = new_drivable_lanes_vec.at(new_drivable_lanes_idx);

    // update left lane
    if (has_same_lane(updated_drivable_lanes.left_lane, convert_to_lanes(new_drivable_lanes))) {
      updated_drivable_lanes.left_lane = new_drivable_lanes.left_lane;
    }
    // update right lane
    if (has_same_lane(updated_drivable_lanes.right_lane, convert_to_lanes(new_drivable_lanes))) {
      updated_drivable_lanes.right_lane = new_drivable_lanes.right_lane;
    }
    // update middle lanes
    for (const auto & middle_lane : convert_to_lanes(new_drivable_lanes)) {
      if (!has_same_lane(middle_lane, convert_to_lanes(updated_drivable_lanes))) {
        updated_drivable_lanes.middle_lanes.push_back(middle_lane);
      }
    }

    // validate middle lanes
    auto & middle_lanes = updated_drivable_lanes.middle_lanes;
    if (has_same_lane(updated_drivable_lanes.right_lane, middle_lanes)) {
      middle_lanes.erase(
        std::remove(
          std::begin(middle_lanes), std::end(middle_lanes), updated_drivable_lanes.right_lane),
        std::cend(middle_lanes));
    }
    if (has_same_lane(updated_drivable_lanes.left_lane, middle_lanes)) {
      middle_lanes.erase(
        std::remove(
          std::begin(middle_lanes), std::end(middle_lanes), updated_drivable_lanes.left_lane),
        std::cend(middle_lanes));
    }
  }
  // NOTE: If original_drivable_lanes_vec is shorter than new_drivable_lanes_vec, push back remained
  // new_drivable_lanes_vec.
  if (new_drivable_lanes_idx + 1 < new_drivable_lanes_vec.size()) {
    updated_drivable_lanes_vec.insert(
      updated_drivable_lanes_vec.end(), new_drivable_lanes_vec.begin() + new_drivable_lanes_idx + 1,
      new_drivable_lanes_vec.end());
  }

  return updated_drivable_lanes_vec;
}

void NormalLaneChange::insert_stop_point(
  const lanelet::ConstLanelets & lanelets, PathWithLaneId & path, const bool is_waiting_approval)
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);
  if (lanelets.empty()) {
    return;
  }

  const auto & route_handler = getRouteHandler();

  if (route_handler->getNumLaneToPreferredLane(lanelets.back()) == 0) {
    return;
  }

  const auto & current_lanes = get_current_lanes();
  const auto is_current_lane = lanelets.front().id() == current_lanes.front().id() &&
                               lanelets.back().id() == current_lanes.back().id();

  // if input is not current lane, we can just insert the points at terminal.
  if (!is_current_lane) {
    if (common_data_ptr_->transient_data.next_dist_buffer.min < calculation::eps) {
      return;
    }
    const auto arc_length_to_stop_pose = motion_utils::calcArcLength(path.points) -
                                         common_data_ptr_->transient_data.next_dist_buffer.min;
    set_stop_pose(arc_length_to_stop_pose, path, "next lc terminal");
    return;
  }

  insert_stop_point_on_current_lanes(path, is_waiting_approval);
}

int RouteHandler::getNumLaneToPreferredLane(
  const lanelet::ConstLanelet & lanelet, const Direction direction) const
{
  if (exists(preferred_lanelets_, lanelet)) {
    return 0;
  }

  if ((direction == Direction::NONE) || (direction == Direction::RIGHT)) {
    const auto right_opt =
      autoware::experimental::lanelet2_utils::right_lanelets(lanelet, routing_graph_ptr_);
    if (right_opt.has_value()) {
      int num{0};
      const auto & right_lanes = *right_opt;
      for (const auto & right : right_lanes) {
        num--;
        if (exists(preferred_lanelets_, right)) {
          return num;
        }
      }
    }
  }

  if ((direction == Direction::NONE) || (direction == Direction::LEFT)) {
    const auto left_opt =
      autoware::experimental::lanelet2_utils::left_lanelets(lanelet, routing_graph_ptr_);
    if (left_opt.has_value()) {
      const auto & left_lanes = *left_opt;
      int num = 0;
      for (const auto & left : left_lanes) {
        num++;
        if (exists(preferred_lanelets_, left)) {
          return num;
        }
      }
    }
  }

  return 0;  // TODO(Horibe) check if return 0 is appropriate.
}

bool exists(const std::vector<LaneletPrimitive> & primitives, const int64_t & id)
{
  for (const auto & p : primitives) {
    if (p.id == id) {
      return true;
    }
  }
  return false;
}

std::optional<lanelet::ConstLanelets> right_lanelets(
  const lanelet::ConstLanelet & lanelet,
  const lanelet::routing::RoutingGraphConstPtr & routing_graph)
{
  lanelet::ConstLanelets lanelets;
  auto right_lane = right_lanelet(lanelet, routing_graph);
  // If the right lane doesn't exist at the first place.
  if (!right_lane.has_value()) {
    return std::nullopt;
  }
  // If the right lane exists.
  while (right_lane.has_value()) {
    lanelets.push_back(right_lane.value());
    right_lane = right_lanelet(right_lane.value(), routing_graph);
  }
  return lanelets;
}

std::optional<lanelet::ConstLanelet> right_lanelet(
  const lanelet::ConstLanelet & lanelet, const lanelet::routing::RoutingGraphConstPtr routing_graph)
{
  if (const auto right_lane = routing_graph->right(lanelet)) {
    // lane changeable
    return *right_lane;
  }
  if (const auto adjacent_right_lane = routing_graph->adjacentRight(lanelet)) {
    return *adjacent_right_lane;
  }
  return std::nullopt;
}

std::optional<lanelet::ConstLanelets> left_lanelets(
  const lanelet::ConstLanelet & lanelet,
  const lanelet::routing::RoutingGraphConstPtr & routing_graph)
{
  lanelet::ConstLanelets lanelets;
  auto left_lane = left_lanelet(lanelet, routing_graph);
  // If the left lane doesn't exist at the first place.
  if (!left_lane.has_value()) {
    return std::nullopt;
  }
  // If the left lane exists.
  while (left_lane.has_value()) {
    lanelets.push_back(left_lane.value());
    left_lane = left_lanelet(left_lane.value(), routing_graph);
  }
  return lanelets;
}

std::optional<lanelet::ConstLanelet> left_lanelet(
  const lanelet::ConstLanelet & lanelet, const lanelet::routing::RoutingGraphConstPtr routing_graph)
{
  if (const auto left_lane = routing_graph->left(lanelet)) {
    // lane changeable
    return *left_lane;
  }
  if (const auto adjacent_left_lane = routing_graph->adjacentLeft(lanelet)) {
    return *adjacent_left_lane;
  }
  return std::nullopt;
}

const lanelet::ConstLanelets & get_current_lanes() const
{
  return common_data_ptr_->lanes_ptr->current;
}

void NormalLaneChange::set_stop_pose(
  const double arc_length_to_stop_pose, PathWithLaneId & path, const std::string & reason)
{
  const auto stop_point = utils::insertStopPoint(arc_length_to_stop_pose, path);
  lane_change_stop_pose_ = PoseWithDetailOpt(PoseWithDetail(stop_point.point.pose, reason));
}

PathPointWithLaneId insertStopPoint(const double length, PathWithLaneId & path)
{
  const size_t original_size = path.points.size();

  // insert stop point
  const auto insert_idx = autoware::motion_utils::insertStopPoint(length, path.points);
  if (!insert_idx) {
    return PathPointWithLaneId();
  }

  // check if a stop point is inserted
  if (path.points.size() == original_size) {
    return path.points.at(*insert_idx);
  }

  if (*insert_idx == 0 || *insert_idx == original_size - 1) {
    return path.points.at(*insert_idx);
  }

  // check lane ids of the inserted stop point
  path.points.at(*insert_idx).lane_ids = {};
