double calc_stopping_distance(const LCParamPtr & lc_param_ptr)
{
  // v^2 = u^2 + 2ad
  const auto min_lc_vel = lc_param_ptr->trajectory.min_lane_changing_velocity;
  const auto min_lon_acc = lc_param_ptr->trajectory.min_longitudinal_acc;
  const auto min_back_dist = std::abs((min_lc_vel * min_lc_vel) / (2 * min_lon_acc));

  const auto param_back_dist = lc_param_ptr->backward_length_buffer_for_end_of_lane;
  return std::max(min_back_dist, param_back_dist);
}

bool isEgoWithinOriginalLane(
  const lanelet::BasicPolygon2d & lane_polygon, const Pose & current_pose,
  const BehaviorPathPlannerParameters & common_param, const double outer_margin)
{
  const auto vehicle_poly = autoware_utils::to_footprint(
    current_pose, common_param.base_link2front, common_param.base_link2rear,
    common_param.vehicle_width);

  // Check if the ego vehicle is entirely within the lane with a given outer margin.
  for (const auto & p : vehicle_poly.outer()) {
    // When the point is in the polygon, the distance is 0. When it is out of the polygon, return a
    // positive value.
    const auto dist = boost::geometry::distance(p, lane_polygon);
    if (dist > std::max(outer_margin, 0.0)) {
      return false;  // out of polygon
    }
  }

  return true;  // inside polygon
}

Polygon2d to_footprint(
  const geometry_msgs::msg::Pose & base_link_pose, const double base_to_front,
  const double base_to_rear, const double width)
{
  using autoware_utils_geometry::calc_offset_pose;
  Polygon2d polygon;
  const auto point0 = calc_offset_pose(base_link_pose, base_to_front, width / 2.0, 0.0).position;
  const auto point1 = calc_offset_pose(base_link_pose, base_to_front, -width / 2.0, 0.0).position;
  const auto point2 = calc_offset_pose(base_link_pose, -base_to_rear, -width / 2.0, 0.0).position;
  const auto point3 = calc_offset_pose(base_link_pose, -base_to_rear, width / 2.0, 0.0).position;

  append_point_to_polygon(polygon, point0);
  append_point_to_polygon(polygon, point1);
  append_point_to_polygon(polygon, point2);
  append_point_to_polygon(polygon, point3);
  append_point_to_polygon(polygon, point0);

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

void append_point_to_polygon(Polygon2d & polygon, const geometry_msgs::msg::Point & geom_point)
{
  Point2d point;
  point.x() = geom_point.x;
  point.y() = geom_point.y;

  bg::append(polygon.outer(), point);
}

bool is_clockwise(const Polygon2d & polygon)
{
  const int n = polygon.outer().size();
  const double x_offset = polygon.outer().at(0).x();
  const double y_offset = polygon.outer().at(0).y();
  double sum = 0.0;
  for (std::size_t i = 0; i < polygon.outer().size(); ++i) {
    sum +=
      (polygon.outer().at(i).x() - x_offset) * (polygon.outer().at((i + 1) % n).y() - y_offset) -
      (polygon.outer().at(i).y() - y_offset) * (polygon.outer().at((i + 1) % n).x() - x_offset);
  }

  return sum < 0.0;
}

Polygon2d inverse_clockwise(const Polygon2d & polygon)
{
  auto output_polygon = polygon;
  boost::geometry::reverse(output_polygon);
  return output_polygon;
}

double calc_dist_to_last_fit_width(
  const CommonDataPtr & common_data_ptr, const PathWithLaneId & path, const double margin)
{
  const auto & current_lanes = common_data_ptr->lanes_ptr->current;
  const auto & current_lanes_polygon = common_data_ptr->lanes_polygon_ptr->current;
  const auto & bpp_param = *common_data_ptr->bpp_param_ptr;

  autoware_utils::LineString2d line_string;
  line_string.reserve(path.points.size() - 1);
  std::for_each(path.points.begin() + 1, path.points.end(), [&line_string](const auto & point) {
    const auto & position = point.point.pose.position;
    boost::geometry::append(line_string, autoware_utils::Point2d(position.x, position.y));
  });

  const auto & src_pose = path.points.front().point.pose;
  return calc_dist_to_last_fit_width(
    current_lanes, current_lanes_polygon, line_string, src_pose, bpp_param, margin);
}

double calc_dist_to_last_fit_width(
  const lanelet::ConstLanelets & lanelets, const lanelet::BasicPolygon2d & lanelet_polygon,
  const autoware_utils::LineString2d & line_string, const Pose & src_pose,
  const BehaviorPathPlannerParameters & bpp_param, const double margin)
{
  const double buffer_distance = 0.5 * bpp_param.vehicle_width + margin;
  autoware_utils::MultiPolygon2d center_line_polygon;
  namespace strategy = boost::geometry::strategy::buffer;
  boost::geometry::buffer(
    line_string, center_line_polygon, strategy::distance_symmetric<double>(buffer_distance),
    strategy::side_straight(), strategy::join_miter(), strategy::end_flat(),
    strategy::point_square());

  if (center_line_polygon.empty()) return 0.0;

  std::vector<autoware_utils::Point2d> intersection_points;
  boost::geometry::intersection(lanelet_polygon, center_line_polygon, intersection_points);

  if (intersection_points.empty()) {
    return utils::getDistanceToEndOfLane(src_pose, lanelets);
  }

  Pose pose;
  double distance = std::numeric_limits<double>::max();
  for (const auto & point : intersection_points) {
    pose.position.x = boost::geometry::get<0>(point);
    pose.position.y = boost::geometry::get<1>(point);
    distance = std::min(distance, utils::getSignedDistance(src_pose, pose, lanelets));
  }

  return std::max(distance - (bpp_param.base_link2front + margin), 0.0);
}

double getDistanceToEndOfLane(const Pose & current_pose, const lanelet::ConstLanelets & lanelets)
{
  const auto & arc_coordinates =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelets, current_pose);
  const double lanelet_length = lanelet::geometry::length3d(lanelet::LaneletSequence(lanelets));
  return lanelet_length - arc_coordinates.length;
}

