Direction getDirection() const
{
  if (direction_ == Direction::NONE && !status_.lane_change_path.path.points.empty()) {
    const auto lateral_shift = utils::lane_change::getLateralShift(status_.lane_change_path);
    return lateral_shift > 0.0 ? Direction::LEFT : Direction::RIGHT;
  }

  return direction_;
}

double getLateralShift(const LaneChangePath & path)
{
  if (path.shifted_path.shift_length.empty()) {
    return 0.0;
  }

  const auto start_idx =
    std::min(path.info.shift_line.start_idx, path.shifted_path.shift_length.size() - 1);
  const auto end_idx =
    std::min(path.info.shift_line.end_idx, path.shifted_path.shift_length.size() - 1);

  return path.shifted_path.shift_length.at(end_idx) - path.shifted_path.shift_length.at(start_idx);
}

void add(
  const double distance, const Pose & control_point_pose, const uint16_t behavior,
  const SafetyFactorArray & safety_factors, const bool is_driving_forward = true,
  const double velocity = 0.0, const double shift_length = 0.0, const std::string & detail = "")
{
  const auto control_point = autoware_internal_planning_msgs::build<ControlPoint>()
                               .pose(control_point_pose)
                               .velocity(velocity)
                               .shift_length(shift_length)
                               .distance(distance);

  const auto factor = autoware_internal_planning_msgs::build<PlanningFactor>()
                        .module(name_)
                        .is_driving_forward(is_driving_forward)
                        .control_points({control_point})
                        .behavior(behavior)
                        .detail(detail)
                        .safety_factors(safety_factors);

  factors_.push_back(factor);
}

void updateRTCStatus(
  const double start_distance, const double finish_distance, const bool safe,
  const uint8_t & state)
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);
  for (const auto & [module_name, ptr] : rtc_interface_ptr_map_) {
    if (ptr) {
      ptr->updateCooperateStatus(
        uuid_map_.at(module_name), safe, state, start_distance, finish_distance, clock_->now());
    }
  }
}

void RTCInterface::updateCooperateStatus(
  const UUID & uuid, const bool safe, const uint8_t state, const double start_distance,
  const double finish_distance, const rclcpp::Time & stamp, const bool requested,
  const std::optional<bool> & override_rtc_auto_mode)
{
  std::lock_guard<std::mutex> lock(mutex_);
  // Find registered status which has same uuid
  auto itr = std::find_if(
    registered_status_.statuses.begin(), registered_status_.statuses.end(),
    [uuid](const auto & s) { return s.uuid == uuid; });

  // If there is no registered status, add it
  if (itr == registered_status_.statuses.end()) {
    CooperateStatus status;
    status.stamp = stamp;
    status.uuid = uuid;
    status.module = module_;
    status.safe = safe;
    status.requested = requested;
    status.command_status.type = Command::DEACTIVATE;
    status.state.type = State::WAITING_FOR_EXECUTION;
    status.start_distance = start_distance;
    status.finish_distance = finish_distance;
    status.auto_mode = override_rtc_auto_mode.value_or(is_auto_mode_enabled_);
    registered_status_.statuses.push_back(status);

    if (state != State::WAITING_FOR_EXECUTION)
      RCLCPP_WARN_STREAM(
        getLogger(), "[updateCooperateStatus]  Cannot register "
                       << state_to_string(state) << " as initial state" << std::endl);

    return;
  }

  auto update_status = [&](auto & status) {
    status.stamp = stamp;
    status.safe = safe;
    status.requested = requested;
    status.state.type = state;
    status.start_distance = start_distance;
    status.finish_distance = finish_distance;
  };

  // If the registered status is found, update status by considering the state transition
  if (
    itr->state.type == State::WAITING_FOR_EXECUTION &&
    (state == State::WAITING_FOR_EXECUTION || state == State::RUNNING || state == State::FAILED)) {
    update_status(*itr);
    return;
  }

  if (itr->state.type == State::RUNNING && state != State::WAITING_FOR_EXECUTION) {
    update_status(*itr);
    return;
  }

  if (itr->state.type == State::ABORTING && (state == State::ABORTING || state == State::FAILED)) {
    update_status(*itr);
    return;
  }

  if (itr->state.type == state) {
    update_status(*itr);
    return;
  }

  RCLCPP_WARN_STREAM(
    getLogger(), "[updateCooperateStatus] uuid : " << uuid_to_string(uuid)
                                                   << " cannot transit from "
                                                   << state_to_string(itr->state.type) << " to "
                                                   << state_to_string(state) << std::endl);
}
